CREATE TABLE "users" ("id" uuid DEFAULT gen_random_uuid(),"username" varchar(50) NOT NULL,"name" varchar(100) NOT NULL,"password_hash" varchar(255) NOT NULL,"is_admin" boolean NOT NULL DEFAULT false,"created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"deleted_at" timestamptz,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_users_deleted_at" ON "users" ("deleted_at");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_users_username" ON "users" ("username");
CREATE TABLE "groups" ("id" uuid DEFAULT gen_random_uuid(),"name" varchar(100) NOT NULL,"description" varchar(255) NOT NULL DEFAULT '',"created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "idx_groups_name" ON "groups" ("name");
CREATE TABLE "group_members" ("group_id" uuid,"user_id" uuid,"created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY ("group_id","user_id"),CONSTRAINT "fk_group_members_group" FOREIGN KEY ("group_id") REFERENCES "groups"("id") ON DELETE CASCADE,CONSTRAINT "fk_group_members_user" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS "idx_group_members_user_id" ON "group_members" ("user_id");
CREATE TABLE "sessions" ("id" uuid DEFAULT gen_random_uuid(),"user_id" uuid NOT NULL,"token_hash" bytea NOT NULL,"prev_token_hash" bytea,"prev_valid_until" timestamptz,"csrf_token" varchar(64) NOT NULL,"created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"last_seen_at" timestamptz NOT NULL,"rotated_at" timestamptz NOT NULL,"absolute_expires_at" timestamptz NOT NULL,"revoked_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_sessions_user" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS "idx_sessions_prev_token_hash" ON "sessions" ("prev_token_hash");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_sessions_token_hash" ON "sessions" ("token_hash");
CREATE INDEX IF NOT EXISTS "idx_sessions_user_id" ON "sessions" ("user_id");
CREATE TABLE "db_connections" ("id" uuid DEFAULT gen_random_uuid(),"name" varchar(100) NOT NULL,"host" varchar(255) NOT NULL,"port" bigint NOT NULL DEFAULT 5432,"db_name" varchar(100) NOT NULL,"username" varchar(100) NOT NULL,"password_enc" bytea NOT NULL,"ssl_mode" varchar(20) NOT NULL DEFAULT 'prefer',"created_by" varchar(64),"created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"deleted_at" timestamptz,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_db_connections_deleted_at" ON "db_connections" ("deleted_at");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_db_connections_name" ON "db_connections" ("name") WHERE deleted_at IS NULL;
CREATE TABLE "group_database_access" ("group_id" uuid,"connection_id" uuid,"level" varchar(10) NOT NULL,"created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY ("group_id","connection_id"),CONSTRAINT "fk_group_database_access_group" FOREIGN KEY ("group_id") REFERENCES "groups"("id") ON DELETE CASCADE,CONSTRAINT "fk_group_database_access_connection" FOREIGN KEY ("connection_id") REFERENCES "db_connections"("id") ON DELETE CASCADE,CONSTRAINT "chk_group_database_access_level" CHECK (level IN ('view','edit')));
CREATE INDEX IF NOT EXISTS "idx_group_database_access_connection_id" ON "group_database_access" ("connection_id");
CREATE TABLE "migrations" ("id" uuid DEFAULT gen_random_uuid(),"connection_id" uuid NOT NULL,"version" bigint,"name" varchar(200) NOT NULL,"sql" text NOT NULL,"status" varchar(10) NOT NULL DEFAULT 'draft',"error" text NOT NULL DEFAULT '',"created_by" varchar(64) NOT NULL,"executed_by" varchar(64),"created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"executed_at" timestamptz,"duration_ms" bigint,PRIMARY KEY ("id"),CONSTRAINT "fk_migrations_connection" FOREIGN KEY ("connection_id") REFERENCES "db_connections"("id") ON DELETE RESTRICT,CONSTRAINT "chk_migrations_status" CHECK (status IN ('draft','success','failed')));
CREATE UNIQUE INDEX IF NOT EXISTS "idx_migrations_connection_version" ON "migrations" ("connection_id","version") WHERE version IS NOT NULL;
CREATE INDEX IF NOT EXISTS "idx_migrations_connection_id" ON "migrations" ("connection_id");
CREATE TABLE "migration_batches" ("id" uuid DEFAULT gen_random_uuid(),"connection_id" uuid NOT NULL,"status" varchar(10) NOT NULL DEFAULT 'queued',"total" bigint NOT NULL DEFAULT 0,"processed" bigint NOT NULL DEFAULT 0,"failed" bigint NOT NULL DEFAULT 0,"last_id" bigint NOT NULL DEFAULT 0,"cancel_requested" boolean NOT NULL DEFAULT false,"created_by" varchar(64) NOT NULL,"cancelled_by" varchar(64),"error" text NOT NULL DEFAULT '',"heartbeat_at" timestamptz,"started_at" timestamptz,"finished_at" timestamptz,"created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY ("id"),CONSTRAINT "fk_migration_batches_connection" FOREIGN KEY ("connection_id") REFERENCES "db_connections"("id") ON DELETE RESTRICT,CONSTRAINT "chk_migration_batches_status" CHECK (status IN ('queued','running','success','partial','failed','cancelled')));
CREATE INDEX IF NOT EXISTS "idx_migration_batches_connection_created" ON "migration_batches" ("connection_id","created_at" DESC);
CREATE TABLE "migration_batch_items" ("id" bigserial,"batch_id" uuid NOT NULL,"migration_id" uuid NOT NULL,"attempt" bigint NOT NULL DEFAULT 1,"execution_id" uuid NOT NULL DEFAULT gen_random_uuid(),"status" varchar(10) NOT NULL DEFAULT 'pending',"error" text NOT NULL DEFAULT '',"compensation_status" varchar(12) NOT NULL DEFAULT 'none',"compensated_at" timestamptz,"started_at" timestamptz,"finished_at" timestamptz,"duration_ms" bigint,"created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY ("id"),CONSTRAINT "fk_migration_batch_items_batch" FOREIGN KEY ("batch_id") REFERENCES "migration_batches"("id") ON DELETE CASCADE,CONSTRAINT "fk_migration_batch_items_migration" FOREIGN KEY ("migration_id") REFERENCES "migrations"("id") ON DELETE RESTRICT,CONSTRAINT "chk_migration_batch_items_status" CHECK (status IN ('pending','running','success','failed','skipped')),CONSTRAINT "chk_migration_batch_items_compensation" CHECK (compensation_status IN ('none','retained','rolled_back')));
CREATE UNIQUE INDEX IF NOT EXISTS "idx_batch_items_batch_migration" ON "migration_batch_items" ("batch_id","migration_id");
CREATE INDEX IF NOT EXISTS "idx_batch_items_batch_id" ON "migration_batch_items" ("batch_id","id");
CREATE INDEX IF NOT EXISTS "idx_batch_items_migration" ON "migration_batch_items" ("migration_id");
